effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

      vec4 perm(vec4 x) { x = ((x * 34.0) + 1.0) * x; return x - floor(x * (1.0 / 289.0)) * 289.0; }

      float noise(vec3 p)
      {
          vec3 a = floor(p);
          vec3 d = p - a;
          d = d * d * (3.0 - 2.0 * d);

          vec4 b = a.xxyy + vec4(0.0, 1.0, 0.0, 1.0);
          vec4 k1 = perm(b.xyxy);
          vec4 k2 = perm(k1.xyxy + b.zzww);

          vec4 c = k2 + a.zzzz;
          vec4 k3 = perm(c);
          vec4 k4 = perm(c + 1.0);

          vec4 o1 = fract(k3 * 0.02439024);
          vec4 o2 = fract(k4 * 0.02439024);

          vec4 o3 = o2 * d.z + o1 * (1.0 - d.z);
          vec2 o4 = o3.yw * d.x + o3.xz * (1.0 - d.x);

          return o4.y * d.y + o4.x * (1.0 - d.y);
      }

      float specular(vec3 light_dir, vec3 ray_dir, vec3 normal)
      {
          return max(0.0, dot(normal, normalize(light_dir + ray_dir)));
      }

      vec4 getColor(vec2 uv, vec3 col, float seed, float min_res)
      {

          float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;
          vec3 p = vec3(uv, iTime * .5 + seed);
          uv += noise(p * 0.7) * 0.35 - noise(-p * xxa) * xxb;
          // uv += noise(p * 0.7) * 0.35 - noise(-p * 1.2) * 0.2;
          float l = length(uv);
          vec3 n = normalize(vec3(uv, -1.0));
          const vec3 light_dir = vec3(0.6666, 0.6666, -0.3333);
          vec3 view_dir = -normalize(vec3(uv, 1.0));

          float light = xxc * pow(specular(light_dir, view_dir, n), 16.0);
          float m = smoothstep(1.0, 1.0 - 3.0 / min_res, l);
          vec3 color = pow(max(0.0, 2.0 - sqrt(l)), (25.0-xxd)) * col;
          // vec3 color = pow(max(0.0, 2.0 - sqrt(l)), 10.0) * col;
          vec3 nc = abs(n + vec3(0, 0, 0.3));
          col = normalize(col + pow(nc, vec3(7.0)) * vec3(7)) + col * 0.35;
          // vec3 nc = abs(n + vec3(0, 0, 0.3));
          // col = normalize(col + pow(nc, vec3(7.0)) * vec3(7)) + col * 0.35;
          color = mix(color, col, m) + light;
          return vec4(color, m);
      }

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

     vec2 umefx;
     // umefx = acScreenNorm; 
     umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     umefx.y*=acLayerSize.y/acLayerSize.x;

     umefx /= scale;
     umefx *= rot2m((0.0+angle)*0.0174533);
     umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     umefx /= scaleVec;

     /////////////////////////

 	vec4 fragColor;


          float min_res = min(iResolution.x, iResolution.y);
          vec2 uv = umefx;
          // (fragCoord * 2.0 - iResolution.xy) / min_res * 1.9;
          vec4 col1 = getColor(uv * 0.98, vec3(color1.rgb), 0.0, min_res);
          vec4 col2 = getColor(uv, vec3(color2.rgb), -612.734, min_res);
          vec3 col = mix(col1.rgb, col2.rgb, clamp(0.5 + 0.5 * (col2.w - col1.w), 0.0, 1.0));
          fragColor = newLayer(color3, vec4(col, 0.0));

 	    vec4 factor = mix(texColorX,fragColor,1.0);
 	    // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         // float luminance = dot(fragColor.rgb, luminanceWeighting);
         // vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    // if(GRADMAP) { factor = mix(texColorX,gradmap,1.0); }

 	    // vec4 xbuffer = texture2DCv(buff1.texture, acScreenNorm.st);

     vec4 resultfinal;
       if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
 	// }
 }
